import {hasUnresolvedTrades} from './trade-save-guard.mjs';
import {prepareSilverMigration,canRestoreBeforeSilver} from './stage3-migration.mjs';
import {prepareFormMigration} from './form-migration.mjs';
import {prepareLayoutMigration} from './layout-migration.mjs';
import {createGame,command,advance,validate,summarize} from './engine.mjs';
import * as persistence from './storage.mjs';
import * as rosterEngine from './roster.mjs';
export class GameSession{
 constructor({storage=persistence,workerFactory=()=>new Worker(new URL('./offline-worker.mjs',import.meta.url),{type:'module'}),now=()=>Date.now(),notify=()=>{},catchUpEnabled=true}={}){Object.assign(this,{storage,workerFactory,now,notify,catchUpEnabled});this.state=null;this.roster=null;this.localView=null;this.revision=0;this.resolvedAt=now();this.stateWallAt=this.resolvedAt;this.phase='loading';this.queue=Promise.resolve();this.importGeneration=0;this.pendingImport=null;this.worker=null;this.workerGeneration=0;this.error=null;this.legacy=[];this.busy=false;this.report=null;this.recovery=null;this.pendingRecovery=null;this.recoveryError=null;this.roomMarker=null}
 changed(){this.notify(this)}
 install(state,roster=null){this.roster=roster;this.localView=roster?rosterEngine.roomView(roster):null;this.state=this.localView?.state??state}
 refreshRoster(){if(this.roster)this.install(null,this.roster)}
 listCharacters(){return this.roster?rosterEngine.members(this.roster):[]}
 offlineReport(before,seconds){const after=this.roster?new Map(rosterEngine.memberViews(this.roster).map(({id,state})=>[id,summarize(state)])):null;return{before,after:summarize(this.state),seconds,...(after&&this.catchupOrigin?.characters?{characters:this.catchupOrigin.characters.map(row=>({...row,after:after.get(row.id)}))}:{})}}
 async recoverRoster(){if(this.roster||!this.state||!this.storage.writeRoster)return;const next=rosterEngine.fromSolo(this.state);await this.persist(next,true,this.stateWallAt,{archive:true,operation:'roster-upgrade'});this.install(null,next)}
 async recoverCurrent(){await this.recoverSilver();await this.recoverForms();await this.recoverLayout();await this.recoverFusion();await this.recoverPetBreeding();await this.recoverRoster()}
 async changeRoster(change,operation){if(this.phase!=='ready'||this.busy||!this.roster)return{ok:false,error:'目前無法調整角色'};this.busy=true;try{const next=structuredClone(this.roster),result=change(next);if(!result.ok)return result;await this.persist(next,true,this.stateWallAt,{operation});this.install(null,next);return result}catch(error){this.block(error);return{ok:false,error:error.message}}finally{this.busy=false;this.changed()}}
 selectCharacter(id){return this.changeRoster(roster=>rosterEngine.select(roster,id),'select-character')}
 configureParty(options){return this.changeRoster(roster=>rosterEngine.configureParty(roster,options),'configure-party')}

 block(error){this.error=error instanceof Error?error:Error(String(error));this.phase='blocked';this.workerGeneration++;this.worker?.terminate();this.worker=null;this.changed()}
 start(){if(this.starting)return this.starting;this.starting=this.startInternal().finally(()=>{this.starting=null});return this.starting}
 async retryOwnership(){if(this.phase!=='readonly')return false;await this.start();return this.session?.owned===true&&this.phase!=='blocked'}
 async startInternal(){try{this.session=await this.storage.acquireSession();this.legacy=await this.storage.preserveLegacy();const env=await this.storage.readSave();if(env){this.install(env.state,env.roster??null);this.revision=env.revision;this.resolvedAt=env.resolvedAt;this.stateWallAt=env.resolvedAt;this.roomMarker=env.room??null}if(!this.session.owned){this.phase='readonly';this.changed();return}if(this.state){if(this.resolvedAt>this.now()+1000)throw Error('保存時間晚於本機時間，請確認裝置日期後重新載入。原始進度仍保留，可匯出備份。');if(this.roomMarker){this.phase='room-recovered';this.changed();return}await this.recoverCurrent();await this.catchUp();}else{this.phase='creation';this.changed()}}catch(e){this.block(e);await this.inspectRecovery()}}
 async recoverSilver(){if(this.roster)return;const change=prepareSilverMigration(this.state);if(!change)return;await this.save(change.state,this.stateWallAt,{archive:true,operation:'monster-profile-camp-upgrade'});this.state=change.state;this.silverMigrationNotice=change.notice}
 async recoverForms(){if(this.roster)return;const change=prepareFormMigration(this.state);if(!change)return;await this.save(change.state,this.stateWallAt,{archive:true,operation:'form-collection-upgrade'});this.state=change.state;this.formMigrationNotice=change.notice}
 async recoverLayout(){if(this.roster)return;const change=prepareLayoutMigration(this.state);if(!change)return;await this.save(change.state,this.stateWallAt,{archive:true,operation:'settlement-layout-update'});this.state=change.state;this.layoutNotice=change.notice}
 async recoverFusion(){return this.recoverTransaction('fusion','fusionCommit','recover-reserved-fusion')}
 async recoverPetBreeding(){return this.recoverTransaction('petBreeding','petBreedCommit','recover-reserved-pet-breeding')}
 async recoverTransaction(field,type,operation){if(this.roster){for(const {id,state} of rosterEngine.memberViews(this.roster)){if(!state[field]?.pending)continue;const next=structuredClone(this.roster),selected=next.selectedId;rosterEngine.select(next,id);const result=rosterEngine.command(next,{type,transactionId:state[field].pending.id});if(!result.ok)throw Error(result.error);rosterEngine.select(next,selected);await this.persist(next,true,this.stateWallAt,{operation});this.install(null,next)}return}if(!this.state?.[field]?.pending)return;const next=structuredClone(this.state),result=command(next,{type,transactionId:next[field].pending.id});if(!result.ok)throw Error(result.error);await this.save(next,this.stateWallAt,{operation});this.state=next}
 persist(payload,isRoster,at,options={}){const snapshot=structuredClone(payload);const task=this.queue.then(()=>isRoster?this.storage.writeRoster(snapshot,this.revision,at,options):this.storage.writeSave(snapshot,this.revision,at,options)).then(env=>{this.revision=env.revision;this.resolvedAt=env.resolvedAt;this.roomMarker=env.room??null;return env});this.queue=task.catch(()=>{});return task}
 save(state=this.state,at=this.stateWallAt,options={}){if(!this.roster)return this.persist(state,false,at,options);if(state===this.state)return this.persist(this.roster,true,at,options);const next=structuredClone(this.roster),result=rosterEngine.replaceSelected(next,state);if(!result.ok)return Promise.reject(Error(result.error));return this.persist(next,true,at,options).then(env=>{this.install(null,next);return env})}
 async create(classId,name,attrs,seed=this.now()){if(this.busy||['readonly','blocked','catchup','paused','rollback-ready','recovery-ready','room','room-recovered'].includes(this.phase))return{ok:false,error:'目前無法建立角色'};if(this.roster)return this.changeRoster(roster=>{const result=rosterEngine.createMember(roster,{classId,name,allocated:attrs,seed});if(result.ok)rosterEngine.select(roster,result.memberId);return result},'create-character');this.busy=true;try{const next=createGame(classId,name,attrs,seed),roster=this.storage.writeRoster?rosterEngine.fromSolo(next):null;await this.persist(roster??next,!!roster,this.now(),{archive:!!this.state,operation:'create-adventure'});this.install(next,roster);this.stateWallAt=this.resolvedAt;this.phase='ready';this.report=null;return{ok:true,...(roster?{memberId:roster.selectedId}:{})}}catch(e){this.block(e);return{ok:false,error:e.message}}finally{this.busy=false;this.changed()}}
 async act(action){if(this.phase!=='ready'||this.busy||!this.state)return{ok:false,error:'目前無法操作'};this.busy=true;const previous=structuredClone(this.state),previousRoster=this.roster&&structuredClone(this.roster);try{const result=this.roster?rosterEngine.command(this.roster,action):command(this.state,action);if(!result.ok)return result;this.refreshRoster();await this.save(this.state,this.stateWallAt,{operation:action.type});this.changed();return result}catch(e){this.install(previous,previousRoster);this.block(e);return{ok:false,error:e.message}}finally{this.busy=false;this.changed()}}
 tick(seconds){if(this.phase!=='ready'||this.busy||!this.state)return[];try{const result=this.roster?rosterEngine.advance(this.roster,seconds):advance(this.state,seconds);this.refreshRoster();this.stateWallAt+=seconds*1000;return result.events}catch(e){this.block(e);return[]}}
 async checkpoint(){if(this.phase!=='ready'||this.busy||!this.state)return;try{await this.save()}catch(e){this.block(e)}}
 async catchUp({offline=this.catchupOffline??true}={}){if(this.rollbackRestored||['recovery-ready','room','room-recovered'].includes(this.phase))return;if(!this.state||this.busy||!this.session?.owned||this.phase==='catchup')return;if(!this.catchUpEnabled)return this.resumeWithoutCatchUp({offline});this.catchupOffline=offline;this.catchupPauseRequested=false;this.phase='catchup';this.changed();const generation=++this.workerGeneration;try{await this.queue;const env=await this.storage.readSave();if(generation!==this.workerGeneration)return;this.install(env.state,env.roster??null);this.revision=env.revision;this.resolvedAt=env.resolvedAt;this.stateWallAt=env.resolvedAt;if(env.resolvedAt>this.now()+1000)throw Error('保存時間晚於本機時間，請確認裝置日期後重新載入。原始進度仍保留，可匯出備份。');const seconds=Math.max(0,(this.now()-env.resolvedAt)/1000);if(seconds<.001){this.phase='ready';this.changed();return}this.catchupOrigin??={before:summarize(this.state),start:env.resolvedAt,characters:this.roster?rosterEngine.memberViews(this.roster).map(({id,state})=>({id,name:state.player.name,before:summarize(state)})):null};const originalBefore=this.catchupOrigin.before,start=env.resolvedAt;let base=start;this.progress={processed:0,total:seconds};await new Promise((resolve,reject)=>{const worker=this.workerFactory();this.worker=worker;let commits=Promise.resolve();worker.onerror=e=>reject(Error(e.message||'離線計算中斷'));worker.onmessage=({data:d})=>{if(generation!==this.workerGeneration)return;if(d.type==='error'){reject(Error(d.message));return}if(!['checkpoint','done','paused'].includes(d.type))return;const v=this.roster?rosterEngine.validateRoster(d.roster):validate(d.state);if(!v.ok){reject(Error(v.errors.join('；')));return}commits=commits.then(async()=>{if(generation!==this.workerGeneration)return;await this.persist(d.roster??d.state,!!d.roster,base+d.processed*1000,{operation:'offline-checkpoint'});this.install(d.state,d.roster??null);this.stateWallAt=base+d.processed*1000;this.progress={processed:d.processed,total:d.total};this.changed();if(d.type==='checkpoint'&&d.checkpointId!==undefined)worker.postMessage({type:'ack',checkpointId:d.checkpointId})});commits.catch(reject);if(d.type==='done'||d.type==='paused'){worker.terminate();this.worker=null;commits.then(()=>{if(generation!==this.workerGeneration)return;this.phase=d.type==='paused'?'paused':'ready';if(offline)this.report=this.offlineReport(originalBefore,(this.resolvedAt-this.catchupOrigin.start)/1000);resolve()}).catch(reject)}};worker.postMessage({type:'simulate',...(this.roster?{roster:this.roster}:{state:this.state}),seconds,offline});if(this.catchupPauseRequested)worker.postMessage({type:'pause'})});if(this.phase==='ready'&&generation===this.workerGeneration){const tail=(this.now()-this.resolvedAt)/1000;if(tail>.25){await this.catchUp({offline});return}if(tail>0){const at=this.now();if(this.roster){rosterEngine.advance(this.roster,(at-this.stateWallAt)/1000,{offline});this.refreshRoster()}else advance(this.state,(at-this.stateWallAt)/1000,{offline});this.stateWallAt=at;await this.save(this.state,at,{operation:'offline-tail'})}}if(this.phase==='ready'){if(offline)this.report=this.offlineReport(this.catchupOrigin.before,(this.stateWallAt-this.catchupOrigin.start)/1000);this.catchupOrigin=null}this.changed()}catch(e){this.block(e)}}
 // Temporary site policy: preserve earned state, discard elapsed absence without simulation.
 async resumeWithoutCatchUp({offline}){
  if(!['loading','ready','paused'].includes(this.phase))return;
  this.busy=true;
  try{
   await this.queue;
   const at=this.now();
   if(this.stateWallAt>at+1000)throw Error('保存時間晚於本機時間，請確認裝置日期後重新載入。原始進度仍保留，可匯出備份。');
   if(offline&&at>this.stateWallAt)await this.save(this.state,at,{operation:'offline-suspended'});
   this.stateWallAt=this.now();this.report=null;this.catchupOrigin=null;this.progress=null;this.phase='ready';
  }catch(error){this.block(error)}finally{this.busy=false;this.changed()}
 }
 pauseCatchUp(){if(this.phase==='catchup'){this.catchupPauseRequested=true;this.worker?.postMessage({type:'pause'})}}
 cancelImport(){this.importGeneration++;this.pendingImport=null;this.changed()}
 async selectImport(file){const generation=++this.importGeneration;this.pendingImport=null;if(!file)return;if(file.size>20*1024*1024)throw Error('備份過大');const raw=await file.text();if(generation!==this.importGeneration)return;const parsed=await this.storage.parseImport(raw);if(generation!==this.importGeneration)return;this.pendingImport=parsed;this.changed()}
 assertCanReplaceSave(){if(hasUnresolvedTrades(this))throw Error('仍有暫鎖或尚未完成的交易，請先連回原房主處理；仍可匯出備份與操作其他資產。')}
 async restoreBeforeSilver(){if(!this.pendingImport?.state||this.pendingImport.roster||this.busy||!this.session?.owned||!['ready','creation'].includes(this.phase))return false;this.assertCanReplaceSave();const imported=structuredClone(this.pendingImport.state);if(!canRestoreBeforeSilver(imported))return false;this.busy=true;try{await this.persist(imported,false,this.now(),{archive:!!this.state,operation:'restore-before-monster-upgrade-no-simulation'});this.install(imported);this.stateWallAt=this.resolvedAt;this.pendingImport=null;this.importGeneration++;this.report=null;this.rollbackRestored=true;this.phase='rollback-ready';return true}catch(e){this.block(e);return false}finally{this.busy=false;this.changed()}}
 async restoreBeforeUpgrade(){if(!this.pendingImport?.state||this.pendingImport.roster||this.busy||!this.session?.owned||!['ready','creation'].includes(this.phase))return false;this.assertCanReplaceSave();const imported=structuredClone(this.pendingImport.state);if(!canRestoreBeforeSilver(imported)||imported.formProgress!==undefined||!validate(imported).ok||JSON.stringify(imported).includes('ITEM-FORM-CONTRACT-'))return false;this.busy=true;try{await this.persist(imported,false,this.now(),{archive:!!this.state,operation:'restore-before-upgrade-no-simulation'});this.install(imported);this.stateWallAt=this.resolvedAt;this.pendingImport=null;this.importGeneration++;this.report=null;this.rollbackRestored=true;this.phase='rollback-ready';return true}catch(e){this.block(e);return false}finally{this.busy=false;this.changed()}}
 async confirmImport(){if(!this.pendingImport?.state||this.busy||!['ready','creation'].includes(this.phase))return false;this.assertCanReplaceSave();this.busy=true;const imported=structuredClone(this.pendingImport.state),importedRoster=this.pendingImport.roster&&structuredClone(this.pendingImport.roster),room=this.pendingImport.room,at=Math.min(this.now(),this.pendingImport.resolvedAt??this.now());this.cancelImport();let accepted=false;try{await this.persist(importedRoster??imported,!!importedRoster,at,{archive:!!this.state,operation:'confirmed-import',room});this.install(imported,importedRoster??null);this.stateWallAt=this.resolvedAt;if(room){this.phase='room-recovered';this.report=null;accepted=true;return true}await this.recoverCurrent();this.phase='ready';this.report=null;accepted=true;this.changed()}catch(e){this.block(e)}finally{this.busy=false;this.changed()}if(accepted){await this.catchUp({offline:true});return this.phase!=='blocked'}return false}
 async inspectRecovery(){if(!this.storage.inspectRecovery)return null;try{this.recovery=await this.storage.inspectRecovery();this.pendingRecovery=null;this.recoveryError=null;return this.recovery}catch(error){this.recoveryError=error.message;return null}finally{this.changed()}}
 async exportRawSave(){return this.storage.exportRawSave?this.storage.exportRawSave():null}
 selectRecovery(key){this.pendingRecovery=this.recovery?.candidates.find(candidate=>candidate.key===key&&candidate.valid)||null;this.changed();return this.pendingRecovery}
 async confirmRecovery(){if(this.phase!=='blocked'||this.busy||!this.session?.owned||!this.pendingRecovery||!this.recovery?.currentFingerprint)return false;this.busy=true;try{await this.queue;const env=await this.storage.restoreRecovery(this.pendingRecovery.key,this.recovery.currentFingerprint,this.pendingRecovery.fingerprint);this.install(env.state,env.roster??null);this.revision=env.revision;this.resolvedAt=env.resolvedAt;this.stateWallAt=env.resolvedAt;this.roomMarker=env.room??null;this.error=null;this.pendingRecovery=null;this.recovery=null;this.pendingImport=null;this.importGeneration++;this.report=null;this.catchupOrigin=null;this.rollbackRestored=false;this.phase=this.roomMarker?'room-recovered':'recovery-ready';return true}catch(error){this.block(error);await this.inspectRecovery();return false}finally{this.busy=false;this.changed()}}
 async resumeRecovery(){if(this.phase!=='recovery-ready'||this.busy||!this.session?.owned)return false;this.busy=true;let resumed=false;try{if(this.resolvedAt>this.now()+1000)throw Error('保存時間晚於本機時間，請確認裝置日期後繼續');await this.recoverCurrent();this.phase='paused';resumed=true}catch(error){this.block(error);await this.inspectRecovery()}finally{this.busy=false;this.changed()}if(resumed){await this.catchUp({offline:true});return this.phase!=='blocked'}return false}
 async resumeRoomRecovery(){if(this.phase!=='room-recovered'||this.busy||!this.session?.owned||!this.state)return false;this.busy=true;try{if(this.resolvedAt>this.now()+1000)throw Error('保存時間晚於本機時間，請確認裝置日期後繼續');await this.save(this.state,this.now(),{archive:true,operation:'resume-after-room-interruption'});this.stateWallAt=this.resolvedAt;await this.recoverCurrent();this.phase='ready';this.report=null;return true}catch(error){this.block(error);return false}finally{this.busy=false;this.changed()}}
 async export(){if(!this.state)return null;return this.roster?this.storage.exportRoster(structuredClone(this.roster),this.stateWallAt,{room:this.roomMarker??undefined}):this.storage.exportEnvelope(structuredClone(this.state),this.stateWallAt,{room:this.roomMarker??undefined})}
}
